package io.github.jesterportfolio.hearth.quest;

import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.story.*;
import io.github.jesterportfolio.hearth.exploration.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class CourseOutcomeTest {
    final QuestCatalog catalog=CourseResumeTest.catalog();final QuestJournal.View view=CourseResumeTest.view();
    Playthrough plan(){var steps=new ArrayList<Playthrough.Step>();for(String id:List.of("main","report","failed","paid","skipped","done","future"))steps.add(new Playthrough.Step(id,Playthrough.Kind.QUEST,id,"공개 "+id,"기존 기록 확인"));return new Playthrough(steps);}
    CourseOutcome.Board board(QuestJournal.View v){return CourseOutcome.build(plan(),catalog,v,SharedStoryTest.empty(),SharedStory.Phase.READY);}
    @Test void personalCompletionSkipAndPendingRewardAreSeparateAndFutureDefinitionIsHidden(){var b=board(view);assertEquals(2,b.counts().completed());assertEquals(1,b.counts().skipped());assertEquals(1,b.counts().active());assertEquals(1,b.counts().reporting());assertEquals(1,b.counts().failed());assertEquals(1,b.counts().pendingRewards());assertEquals(1,b.counts().heldRewards());assertFalse(String.join(" ",b.book(1).pages()).contains("미수락 미래"));assertFalse(b.course().guide().complete());}
    @Test void sameRegisteredSharedStageIsNotDoubleCountedAndVisitsRemainPersonal(){var x=view.exploration();var story=new ExplorationStore.Story("stage","공개 단계",true,2);var shared=new StoryStore.Snapshot(story,Set.of("stage"),Map.of());var place=new ExplorationView.Place("place","개인 발견","공개 지역","시설","공개 위치","발견",true,true,false);var v=new QuestJournal.View(view.states(),view.journal(),new ExplorationView(true,x.regions(),List.of(place),x.facts(),x.events(),x.members(),story,x.conditions(),x.nextGoal(),x.blockedQuests(),x.branches()),view.completion());var p=new Playthrough(List.of(new Playthrough.Step("reached",Playthrough.Kind.STAGE,"stage","공유 도달","현재 확인"),new Playthrough.Step("finished",Playthrough.Kind.STAGE_COMPLETE,"stage","공유 완료","현재 확인"),new Playthrough.Step("place",Playthrough.Kind.PLACE,"place","발견","개인 기록")));var b=CourseOutcome.build(p,catalog,v,shared,SharedStory.Phase.READY);assertEquals(1,b.counts().sharedReached());assertEquals(1,b.counts().sharedCompleted());assertEquals(1,b.counts().discovered());assertEquals(1,b.counts().visited());assertEquals(0,b.counts().completed());assertTrue(b.course().guide().complete());}
    @Test void paidOrHeldRewardChangesInvalidateOldResultWithoutGrantingAnything(){var old=board(view);var c=new QuestCompletionView(true,5,Map.of("paid",new QuestCompletionView.Reward("GRANTED","지급 완료",false)),List.of());var v=new QuestJournal.View(view.states(),view.journal(),view.exploration(),c);var paid=board(v);assertEquals(0,paid.counts().pendingRewards());assertEquals(1,paid.counts().grantedRewards());assertThrows(IllegalStateException.class,()->CourseOutcome.require(paid,old,1,null));assertTrue(view.completion().rewards().get("paid").claimable());}
    @Test void sourceRevisionAndBlockedAccessRejectOldResultAndForeignItem(){var old=board(view);var states=new HashMap<>(view.states());states.put("main",new QuestStore.Saved(QuestStore.Phase.ACTIVE,1,1));var fresh=board(new QuestJournal.View(states,view.journal(),view.exploration(),view.completion()));assertThrows(IllegalStateException.class,()->CourseOutcome.require(fresh,old,1,null));var x=view.exploration();var v=new QuestJournal.View(view.states(),view.journal(),new ExplorationView(x.registered(),x.regions(),x.places(),x.facts(),x.events(),x.members(),x.story(),x.conditions(),x.nextGoal(),Set.of("paid"),x.branches()),view.completion());assertEquals(0,board(v).counts().pendingRewards());assertThrows(IllegalStateException.class,()->CourseOutcome.require(board(v),old,1,null));var foreign=new CourseOutcome.Item(new PlaythroughOverview.Row("foreign",PlaythroughOverview.Kind.PERSONAL,"다른 항목","완료",false,true,false,"paid",3,List.of()),null);assertThrows(IllegalStateException.class,()->CourseOutcome.require(old,old,1,foreign));}
    @Test void holdIsUnavailableAndNeverClaimsEmptySuccessfulCourse(){var b=CourseOutcome.build(plan(),catalog,view,SharedStoryTest.empty(),SharedStory.Phase.HOLD);assertFalse(b.available());assertTrue(b.items().isEmpty());assertFalse(b.course().guide().complete());assertThrows(IllegalStateException.class,()->CourseOutcome.require(b,b,1,null));assertTrue(String.join("",b.book(1).pages()).replaceAll("\\s","").contains("확인하지못했습니다"));}
    @Test void resultQueriesAreImmutableAndDoNotReplayStoryOrPayRewards(){String before=view.toString();var b=board(view);b.book(1);assertEquals(before,view.toString());assertThrows(UnsupportedOperationException.class,()->b.items().clear());CourseOutcome.require(b,b,1,b.page(1).getFirst());assertEquals(1,b.pages());assertThrows(IllegalArgumentException.class,()->b.page(2));}
}
